import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/providers")
public class ProviderController {

    private final ProviderService providerService;

    public ProviderController(ProviderService providerService) {
        this.providerService = providerService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Map<String, Object>>> register(@RequestBody ProviderRegisterRequest request,
                                                                     Authentication authentication) {
        if (isBlank(request.getName()) || isBlank(request.getBaseUrl())
                || isBlank(request.getApiKey()) || isBlank(request.getModelId())) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(ApiResponse.error(400, "name、baseUrl、apiKey、modelId不能为空"));
        }
        ModelProvider provider = providerService.register(request, authentication.getName());
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("createdAt", toStringOrNull(provider.getCreatedAt()));
        return ResponseEntity.ok(ApiResponse.success("注册成功", data));
    }

    @PostMapping("/{id}/validate")
    public ResponseEntity<ApiResponse<Map<String, Object>>> validate(@PathVariable("id") Long id,
                                                                     Authentication authentication) {
        ModelProvider provider = providerService.validateProvider(id, authentication.getName());
        if (provider == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, "Provider不存在或无权限"));
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("status", provider.getStatus());
        data.put("lastValidatedAt", toStringOrNull(provider.getLastValidatedAt()));
        return ResponseEntity.ok(ApiResponse.success("验证完成", data));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> list(Authentication authentication) {
        List<ModelProvider> providers = providerService.listProviders(authentication.getName());
        List<Map<String, Object>> data = new ArrayList<>();
        for (ModelProvider provider : providers) {
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("id", provider.getId());
            item.put("name", provider.getName());
            item.put("baseUrl", provider.getBaseUrl());
            item.put("modelId", provider.getModelId());
            item.put("status", provider.getStatus());
            item.put("createdAt", toStringOrNull(provider.getCreatedAt()));
            data.add(item);
        }
        return ResponseEntity.ok(ApiResponse.success("success", data));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<Map<String, Object>>> detail(@PathVariable("id") Long id,
                                                                   Authentication authentication) {
        ModelProvider provider = providerService.getProvider(id, authentication.getName());
        if (provider == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, "Provider不存在或无权限"));
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("errorMessage", provider.getErrorMessage());
        data.put("lastValidatedAt", toStringOrNull(provider.getLastValidatedAt()));
        data.put("createdAt", toStringOrNull(provider.getCreatedAt()));
        return ResponseEntity.ok(ApiResponse.success("success", data));
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private String toStringOrNull(LocalDateTime value) {
        return value == null ? null : value.toString();
    }
}

