package com.modelgate.platform.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.modelgate.platform.dto.ProviderRegisterRequest;
import com.modelgate.platform.entity.ModelProvider;
import com.modelgate.platform.entity.User;
import com.modelgate.platform.mapper.ModelProviderMapper;
import com.modelgate.platform.mapper.UserMapper;
import org.springframework.stereotype.Service;

import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class ProviderService {

    private static final int CONNECT_TIMEOUT_MS = 10000;
    private static final int READ_TIMEOUT_MS = 10000;

    private static final String STATUS_PENDING = "PENDING";
    private static final String STATUS_VALID = "VALID";
    private static final String STATUS_INVALID = "INVALID";
    private static final String STATUS_ERROR = "ERROR";

    private final ModelProviderMapper providerMapper;
    private final UserMapper userMapper;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public ProviderService(ModelProviderMapper providerMapper, UserMapper userMapper) {
        this.providerMapper = providerMapper;
        this.userMapper = userMapper;
    }

    public ModelProvider register(ProviderRegisterRequest request, String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return null;
        }
        ModelProvider provider = new ModelProvider();
        provider.setUserId(user.getId());
        provider.setName(request.getName());
        provider.setBaseUrl(request.getBaseUrl());
        provider.setApiKey(request.getApiKey());
        provider.setModelId(request.getModelId());
        provider.setStatus(STATUS_PENDING);
        provider.setErrorMessage(null);
        provider.setLastValidatedAt(null);
        provider.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        providerMapper.insert(provider);
        return provider;
    }

    public List<ModelProvider> listProviders(String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return Collections.emptyList();
        }
        return providerMapper.findByUserId(user.getId());
    }

    public ModelProvider getProvider(Long id, String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return null;
        }
        ModelProvider provider = providerMapper.findById(id);
        if (provider == null || !user.getId().equals(provider.getUserId())) {
            return null;
        }
        return provider;
    }

    public ModelProvider validateProvider(Long id, String username) {
        ModelProvider provider = getProvider(id, username);
        if (provider == null) {
            return null;
        }
        runValidation(provider);
        provider.setLastValidatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        providerMapper.update(provider);
        return provider;
    }

    private void runValidation(ModelProvider provider) {
        try {
            Integer phaseOneStatus = httpGet(
                    provider.getBaseUrl() + "/models/" + provider.getModelId(), provider.getApiKey());
            if (phaseOneStatus != null && (phaseOneStatus == 401 || phaseOneStatus == 403)) {
                markInvalid(provider, phaseOneStatus);
                return;
            }
            if (phaseOneStatus != null && phaseOneStatus != 404) {
                markValid(provider);
                return;
            }
            Integer phaseTwoStatus = httpPost(
                    provider.getBaseUrl() + "/v1/chat/completions", provider.getApiKey(),
                    buildChatProbeBody(provider.getModelId()));
            if (phaseTwoStatus == null) {
                provider.setStatus(STATUS_ERROR);
                provider.setErrorMessage("Connection failed");
            } else if (phaseTwoStatus == 401 || phaseTwoStatus == 403) {
                markInvalid(provider, phaseTwoStatus);
            } else {
                markValid(provider);
            }
        } catch (Exception e) {
            provider.setStatus(STATUS_ERROR);
            provider.setErrorMessage(e.getMessage());
        }
    }

    private void markValid(ModelProvider provider) {
        provider.setStatus(STATUS_VALID);
        provider.setErrorMessage(null);
    }

    private void markInvalid(ModelProvider provider, int httpStatus) {
        provider.setStatus(STATUS_INVALID);
        provider.setErrorMessage("API key is invalid (HTTP " + httpStatus + ")");
    }

    private String buildChatProbeBody(String modelId) throws Exception {
        Map<String, Object> message = new LinkedHashMap<>();
        message.put("role", "user");
        message.put("content", "ping");
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("model", modelId);
        body.put("messages", Collections.singletonList(message));
        body.put("max_tokens", 1);
        return objectMapper.writeValueAsString(body);
    }

    private Integer httpGet(String url, String apiKey) {
        HttpURLConnection connection = null;
        try {
            connection = openConnection(url, apiKey);
            connection.setRequestMethod("GET");
            return connection.getResponseCode();
        } catch (Exception e) {
            return null;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private Integer httpPost(String url, String apiKey, String jsonBody) {
        HttpURLConnection connection = null;
        try {
            connection = openConnection(url, apiKey);
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/json");
            connection.setDoOutput(true);
            try (OutputStream out = connection.getOutputStream()) {
                out.write(jsonBody.getBytes(StandardCharsets.UTF_8));
            }
            return connection.getResponseCode();
        } catch (Exception e) {
            return null;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private HttpURLConnection openConnection(String url, String apiKey) throws Exception {
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        connection.setConnectTimeout(CONNECT_TIMEOUT_MS);
        connection.setReadTimeout(READ_TIMEOUT_MS);
        connection.setRequestProperty("Authorization", "Bearer " + apiKey);
        return connection;
    }
}

package com.modelgate.platform.service;

import groovy.lang.GroovyShell;
import org.springframework.stereotype.Service;

@Service
public class ScriptService {

    public Object evaluateExpression(String script) {
        if (script == null || script.trim().isEmpty()) {
            throw new IllegalArgumentException("Script must not be null or blank");
        }
        try {
            return new GroovyShell().evaluate(script);
        } catch (Exception e) {
            throw new RuntimeException("Failed to evaluate script: " + e.getMessage(), e);
        }
    }
}
